/** Post-fix integration only: do not adopt or run against the unfixed full saturation loop. */
class PackedGeneratedHelperEncodingIntegrationTest {

	@Test
	void aNonNullUnknownProviderKeepsCompleteStableHelpersAndEveryAggregateBag() {
		PackedPredicateRangeProvider unknown = new PackedPredicateRangeProvider() {
			@Override
			public boolean describeObjectRange(IRI predicate, PackedPredicateRange output) {
				return false;
			}

			@Override
			public long predicateRangeVersion() {
				return 1L;
			}
		};
		TupleExpr source = new Group(new Union(branch(iri("T1")), branch(iri("T2"))), List.of(),
				List.of(new GroupElem("n", new Count(Var.of("e"), true))));
		PlanningGraphDomains.capture(source, PlanningGraphDomain.defaultGraph());
		Model data = model();
		String[] types = { "T1", "T2", "T1", "T2", "T1" };
		String[] codes = { "A", "B", "C", "A", "Z" };
		for (int ordinal = 0; ordinal < types.length; ordinal++) {
			data.add(iri("e" + ordinal), RDF.TYPE, iri(types[ordinal]));
			data.add(iri("e" + ordinal), iri("code"), VF.createLiteral(codes[ordinal]));
		}
		List<String> expected = List.of("n=" + VF.createLiteral(BigInteger.valueOf(4)));
		assertEquals(expected, evaluate(data, source), "independent hand/generic aggregate bag");
		PackedQuery first = PackedQueryCodec.encodeForPlanning(source.clone(), unknown);
		PackedQuery second = PackedQueryCodec.encodeForPlanning(source.clone(), unknown);
		assertTrue(first.hasSameCacheIdentity(second), "separate equivalent encodes retain canonical helper identity");
		assertTrue((generatedRuleMask(first) & PackedRuleProofs.FINITE_CODE_TYPE_VALUES) != 0L);
		PackedQueryView view = new PackedQueryView(first);
		int helperDomains = 0;
		for (int id = 1; id <= first.relationCount(); id++) {
			if (first.relOperator(id) != PackedRelOp.BINDING_SET_ASSIGNMENT) {
				continue;
			}
			int assignment = first.relPayload(id);
			int names = first.payloadPrimary(assignment);
			if (first.payloadChildCount(names) != 1) {
				continue;
			}
			int name = first.payloadChild(names, 0);
			if (Set.of("e", "c", "t", "n").contains(first.objectValue(name))) {
				continue;
			}
			assertEquals(1, first.payloadFlags(assignment));
			assertEquals(names, first.payloadSecondary(assignment));
			assertEquals(2, first.payloadChildCount(assignment));
			Set<Object> actualTypes = new HashSet<>();
			for (int ordinal = 0; ordinal < first.payloadChildCount(assignment); ordinal++) {
				int row = first.payloadChild(assignment, ordinal);
				assertEquals(1, first.bindingCount(row));
				assertEquals(name, first.bindingNameId(row, 0));
				actualTypes.add(first.objectValue(first.bindingValueId(row, 0)));
			}
			assertEquals(Set.of(iri("T1"), iri("T2")), actualTypes);
			helperDomains++;
		}
		assertEquals(1, helperDomains, "one complete helper type domain belongs to this producer");
		int checked = 0;
		for (int id = 1; id <= first.relationCount(); id++) {
			if (first.relGroup(id) == first.relGroup(first.rootRelId())) {
				assertEquals(expected, evaluate(data, view.materializeRelation(id)), "complete aggregate bag " + id);
				checked++;
			}
		}
		assertTrue(checked > 1, "the original and a generated code/type alternative must both be checked");
	}

	private static TupleExpr branch(IRI type) {
		BindingSetAssignment targets = new BindingSetAssignment();
		targets.setBindingNames(Set.of("t"));
		MapBindingSet first = new MapBindingSet();
		first.addBinding("t", VF.createLiteral("A"));
		MapBindingSet second = new MapBindingSet();
		second.addBinding("t", VF.createLiteral("B"));
		targets.setBindingSets(List.of(first, second));
		StatementPattern types = new StatementPattern(Var.of("e"), Var.of("rdfType", RDF.TYPE),
				Var.of("typeValue", type));
		StatementPattern codes = new StatementPattern(Var.of("e"), Var.of("codePredicate", iri("code")), Var.of("c"));
		return new Filter(new Join(targets, new Join(types, codes)),
				new Or(new Compare(Var.of("c"), Var.of("t"), Compare.CompareOp.EQ),
						new Compare(Var.of("c"), new ValueConstant(VF.createLiteral("C")), Compare.CompareOp.EQ)));
	}
}
